const d        = $input.first().json;
const formData = $('Parse Form Data').first().json;

// Pull all fields from formData (Parse Form Data) as authoritative source
const ownerId       = formData.ownerId      || d.ownerId      || '';
const sku           = formData.sku          || d.sku          || '';
// BUG12 fix: itemName in formData (set by Parse Form Data from body.name)
const itemName      = formData.itemName     || d.itemName     || '';
const category      = formData.category     || d.category     || '';
// BUG11 fix: sub_category was missing from row
const subCategory   = formData.subCategory  || d.subCategory  || '';
const goldCarat     = formData.goldCarat    || d.goldCarat    || '';
const diamondPurity = formData.diamondPurity|| d.diamondPurity|| '';
const weight        = formData.weight       || d.weight       || null;
const price         = formData.price        || d.price        || null;
const stockQty      = formData.stockQty     || d.stockQty     || '1';
const material      = formData.material     || d.material     || '';
const occasion      = formData.occasion     || d.occasion     || '';
const description   = formData.description  || d.description  || '';
// BUG10 fix: in_stock was hardcoded to true, now reads from form
const inStock       = formData.inStock !== undefined ? formData.inStock : true;

// Images come from Merge All Image Data (upstream node)
var imagesArr = d.allImageUrls || d.imagesArray || [];
if (typeof imagesArr === 'string') {
  try { imagesArr = JSON.parse(imagesArr); } catch(e) { imagesArr = [imagesArr]; }
}

const row = {
  owner_id:             ownerId,
  sku:                  sku,
  name:                 itemName,
  category:             category,
  sub_category:         subCategory,
  gold_carat:           goldCarat,
  diamond_purity:       diamondPurity,
  weight:               parseFloat(weight)  || null,
  price:                parseFloat(price)   || null,
  stock_qty:            parseInt(stockQty)  || 1,
  material:             material,
  occasion:             occasion,
  description:          description,
  in_stock:             inStock,
  is_current:           true,
  images:               imagesArr,
  primary_image_url:    d.primaryUrl || (imagesArr[0] || ''),
  // AI fields (populated by Parse AI Response or Skip AI nodes upstream)
  // [v3 removed] ai_title:             d.aiTitle               || '',
  // [v3 removed] ai_description:       d.aiDetailedDescription || '',
  // [v3 removed] ai_key_features:      d.aiKeyFeatures         || '',
  // [v3 removed] ai_occasions:         d.aiOccasions           || '',
  // [v3 removed] ai_care_instructions: d.aiCareInstructions    || '',
  // [v3 removed] ai_whatsapp_summary:  d.aiWhatsappSummary     || '',
  // [v3 removed] ai_style_tip:         d.aiStyleTip            || '',
};

return [{ json: Object.assign({}, d, {
  supabaseRow:  row,
  imagesArray:  imagesArr,
  allImageUrls: imagesArr
}) }];

const allItems = $input.all();
const formData = $('Parse Form Data').first().json;

// Detect skip path: totalNewImages === 0 means no new uploads
var firstJson = allItems.length > 0 ? allItems[0].json : {};
var skipped   = (firstJson.totalNewImages === 0 || firstJson.skipImageUpload === true);

var allImageUrls, allPublicIds;

if (skipped) {
  // No new uploads — preserve existing image URLs exactly
  allImageUrls = firstJson.allImageUrls
              || firstJson.existingImages
              || formData.existingImages
              || [];
  allPublicIds = [];
} else {
  // Came from Extract Cloudinary URLs — combine existing + new
  var newImages = allItems.map(function(i) { return i.json; });
  allImageUrls  = (formData.existingImages || []).slice();
  newImages.forEach(function(img) {
    if (img.cloudinaryUrl) allImageUrls.push(img.cloudinaryUrl);
  });
  allPublicIds = newImages
    .map(function(img) { return img.cloudinaryPublicId; })
    .filter(Boolean);
}

var imageColumns = {};
allImageUrls.forEach(function(url, idx) {
  imageColumns['image' + (idx + 1) + '_url'] = url;
});
for (var i = allImageUrls.length + 1; i <= 5; i++) {
  imageColumns['image' + i + '_url'] = '';
}

var primaryUrl      = allImageUrls[0] || '';
var primaryPublicId = allPublicIds[0] || '';

var result = Object.assign({}, formData, imageColumns, {
  primaryUrl:          primaryUrl,
  primaryPublicId:     primaryPublicId,
  allImageUrls:        allImageUrls,
  allPublicIds:        allPublicIds,
  totalUploadedImages: allImageUrls.length
});

return [{ json: result }];

return $input.all().map(function(item) {
  var d = item.json;

  // Cloudinary URL optimization:
  // w_1000  → cap width at 1000px (won't upscale smaller images)
  // f_auto  → serve WebP to modern browsers, JPEG/PNG as fallback
  // q_auto  → Cloudinary picks best quality-to-size ratio automatically
  // Result: same image, faster load, less bandwidth, zero manual resizing
  var rawUrl = d.secure_url || '';
  var optimizedUrl = rawUrl
    ? rawUrl.replace('/upload/', '/upload/w_1000,f_auto,q_auto/')
    : '';

  return {
    json: {
      cloudinaryUrl:      optimizedUrl,
      cloudinaryRawUrl:   rawUrl,
      cloudinaryPublicId: d.public_id  || '',
      cloudinaryFormat:   d.format     || '',
      cloudinaryWidth:    d.width      || '',
      cloudinaryHeight:   d.height     || ''
    }
  };
});

const formData = $('Parse Form Data').first().json;
const binary   = $('Parse Form Data').first().binary || {};

// If frontend pre-uploaded to Cloudinary → no binary slots → skip upload
// Pass the pre-uploaded URLs straight through as allImageUrls
if (formData.uploadedSlots.length === 0) {
  var existingUrls = formData.preUploadedImages && formData.preUploadedImages.length > 0
    ? formData.preUploadedImages
    : (formData.existingImages || []);
  return [{
    json: Object.assign({}, formData, {
      skipImageUpload: true,
      totalNewImages:  0,
      allImageUrls:    existingUrls
    })
  }];
}

// Binary upload path (legacy / future direct upload)
var existingCount = (formData.existingImages || []).length;
return formData.uploadedSlots.map(function(slot, index) {
  var imageNumber = existingCount + index + 1;
  return {
    json: Object.assign({}, formData, {
      currentSlot:     slot,
      imageIndex:      imageNumber,
      imageSuffix:     '_img' + imageNumber,
      skipImageUpload: false,
      totalNewImages:  formData.uploadedSlots.length
    }),
    binary: { data: binary[slot] }
  };
});

const item  = $input.first();
const raw   = item.json  || {};
const body  = raw.body   || raw;   // handles JSON nested under .body or flat
const files = item.binary || {};

// ── Field extraction (all possible key variants from frontend) ──────────────
// BUG5 fix: frontend sends `name`, workflow expected item_name/itemName
const itemName      = body.name          || body.item_name    || body.itemName    || 'Unnamed Item';
const goldCarat     = body.gold_carat    || body.goldCarat    || '';
const diamondPurity = body.diamond_purity|| body.diamondPurity|| '';
const description   = body.description  || '';
const price         = body.price        || '';
const weight        = body.weight       || '';
const category      = body.category     || '';
// BUG7 fix: sub_category and in_stock were missing
const subCategory   = body.sub_category || body.subCategory  || '';
const inStock       = body.in_stock !== undefined ? body.in_stock : true;
const stockQty      = body.stock_qty    || body.stockQty     || '1';
const sku           = body.sku          || body.sku_code      || ('SKU-' + Date.now());
const material      = body.material     || '';
const occasion      = body.occasion     || '';
const ownerId       = body.owner_id     || body.ownerId      || '';

// BUG2+3 fix: frontend sends old_product_id (not product_id) for edits
// isEdit is derived from presence of old_product_id, not body.is_edit (never sent)
const oldProductId  = body.old_product_id || body.oldProductId || '';
const isEdit        = !!(oldProductId) || body.is_edit === true || body.is_edit === 'true';

// BUG4 fix: frontend sends regenAI (not regenerate_ai)
const regenerateAI  = body.regenAI === true || body.regenAI === 'true'
                   || body.regenerate_ai === true || body.regenerate_ai === 'true';

// Existing AI fields (sent when editing, to preserve on Skip AI path)
const existingAiTitle            = body.ai_title              || body.existing_ai_title            || '';
const existingAiDescription      = body.ai_description        || body.existing_ai_description      || '';
const existingAiKeyFeatures      = body.ai_key_features       || body.existing_ai_key_features     || '';
const existingAiOccasions        = body.ai_occasions          || body.existing_ai_occasions        || '';
const existingAiCareInstructions = body.ai_care_instructions  || body.existing_ai_care_instructions|| '';
const existingAiWhatsappSummary  = body.ai_whatsapp_summary   || body.existing_ai_whatsapp_summary || '';
const existingAiStyleTip         = body.ai_style_tip          || body.existing_ai_style_tip        || '';

// ── Image handling ───────────────────────────────────────────────────────────
// BUG1 fix: frontend pre-uploads to Cloudinary and sends URLs in body.images[]
// Legacy: binary file slots (image1..image5) — keep for backwards compat
const imageSlots    = ['image1','image2','image3','image4','image5'];
const uploadedSlots = imageSlots.filter(function(slot) { return !!files[slot]; });

// Primary source: body.images array (pre-uploaded Cloudinary URLs from frontend)
var preUploadedImages = [];
if (Array.isArray(body.images)) {
  preUploadedImages = body.images.filter(function(u) { return !!u; });
}

// Legacy fallback: existing_image1..5 keys
var existingImages = [];
for (var i = 1; i <= 5; i++) {
  var key = 'existing_image' + i;
  if (body[key]) existingImages.push(body[key]);
}

// Merge: pre-uploaded URLs take priority
var allKnownImages = preUploadedImages.length > 0 ? preUploadedImages : existingImages;

// Validate: must have at least one image from any source
if (uploadedSlots.length === 0 && allKnownImages.length === 0) {
  throw new Error('At least one product image is required. Received body keys: ' + Object.keys(body).join(', '));
}

if (!ownerId) {
  throw new Error('owner_id is missing. Body keys: ' + Object.keys(body).join(', '));
}

return [{
  json: {
    // Product fields
    itemName, goldCarat, diamondPurity, description,
    price, weight, category, subCategory, stockQty,
    sku, material, occasion, inStock,
    // Auth / edit control
    ownerId, isEdit, oldProductId, regenerateAI,
    // Existing AI (preserved when not regenerating)
    existingAiTitle, existingAiDescription, existingAiKeyFeatures,
    existingAiOccasions, existingAiCareInstructions,
    existingAiWhatsappSummary, existingAiStyleTip,
    // Images
    uploadedSlots,
    existingImages: allKnownImages,
    preUploadedImages,
    totalNewImages: uploadedSlots.length,
    uploadTimestamp: new Date().toISOString()
  },
  binary: files
}];

