const result   = $input.first().json;
const formData = $('Parse Form Data').first().json;
const isEdit   = formData.isEdit === true || String(formData.isEdit) === 'true';

// result is the Supabase GET response
// It's an array: [] = SKU free, [{...}] = SKU exists
var existingCount = 0;
if (Array.isArray(result)) {
  existingCount = result.length;
} else if (result && result.length !== undefined) {
  existingCount = result.length;
}

// SKU is available if:
// - it's an edit (SKU field is locked, can't be changed), OR
// - no existing product has this SKU (for this owner)
const skuAvailable = isEdit || existingCount === 0;

return [{ json: {
  skuAvailable: skuAvailable,
  skuAvailableStr: String(skuAvailable),
  existingCount: existingCount,
  sku: formData.sku
} }];
